#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <map>
#include <memory>
#include <random>
#include <unordered_map>
#include <vector>

#include <benchmark/benchmark.h>

#include "perf_common.h"

namespace NPolymorphism
{
	class IUnitBehavior
	{
	public:
 virtual ~IUnitBehavior() = default;
 virtual uint32_t Evaluate( uint32_t Input ) const = 0;
	};

	class CInfantry final : public IUnitBehavior
	{
	public:
 explicit CInfantry( uint32_t Strength ) : _Strength( Strength ) {}
 uint32_t Evaluate( uint32_t Input ) const override { return Input * 3u + _Strength; }

	private:
 uint32_t _Strength;
	};

	class CCavalry final : public IUnitBehavior
	{
	public:
 explicit CCavalry( uint32_t Strength ) : _Strength( Strength ) {}
 uint32_t Evaluate( uint32_t Input ) const override { return Input * 5u - _Strength; }

	private:
 uint32_t _Strength;
	};

	class CArtillery final : public IUnitBehavior
	{
	public:
 explicit CArtillery( uint32_t Strength ) : _Strength( Strength ) {}
 uint32_t Evaluate( uint32_t Input ) const override { return ( Input ^ _Strength ) * 7u; }

	private:
 uint32_t _Strength;
	};

	enum class EUnitType : uint8_t
	{
 Infantry,
 Cavalry,
 Artillery
	};

	struct SUnit
	{
 uint32_t Strength;
 EUnitType Type;
 uint8_t Padding[ 3 ];
	};

	inline uint32_t EvaluateByTag( const SUnit& Unit, uint32_t Input )
	{
 switch ( Unit.Type )
 {
 case EUnitType::Infantry: return Input * 3u + Unit.Strength;
 case EUnitType::Cavalry: return Input * 5u - Unit.Strength;
 case EUnitType::Artillery: return ( Input ^ Unit.Strength ) * 7u;
 }
 return 0u;
	}

	struct SArmy
	{
 std::vector<std::unique_ptr<IUnitBehavior>> Owned;
 std::vector<IUnitBehavior*> Scattered;
 std::vector<SUnit> Mixed;
 std::vector<SUnit> Grouped;
	};

	SArmy& GetArmy( int32_t Count )
	{
 static std::map<int32_t, SArmy*> Cache;
 auto Found = Cache.find( Count );
 if ( Found != Cache.end() )
 {
 return *Found->second;
 }

 SArmy* pArmy = new SArmy();
 std::mt19937 Rng( 20260801u );

 pArmy->Owned.reserve( Count );
 pArmy->Scattered.reserve( Count );
 pArmy->Mixed.reserve( Count );

 for ( int32_t Index = 0; Index < Count; ++Index )
 {
 const uint32_t Strength = Rng() & 0xFFFFu;
 const EUnitType Type = static_cast<EUnitType>( Rng() % 3u );

 std::unique_ptr<IUnitBehavior> Unit;
 switch ( Type )
 {
 case EUnitType::Infantry: Unit = std::make_unique<CInfantry>( Strength ); break;
 case EUnitType::Cavalry: Unit = std::make_unique<CCavalry>( Strength ); break;
 case EUnitType::Artillery: Unit = std::make_unique<CArtillery>( Strength ); break;
 }
 pArmy->Scattered.push_back( Unit.get() );
 pArmy->Owned.push_back( std::move( Unit ) );

 SUnit Tagged = {};
 Tagged.Strength = Strength;
 Tagged.Type = Type;
 pArmy->Mixed.push_back( Tagged );
 }

 std::shuffle( pArmy->Scattered.begin(), pArmy->Scattered.end(), Rng );

 pArmy->Grouped = pArmy->Mixed;
 std::stable_sort( pArmy->Grouped.begin(), pArmy->Grouped.end(),
 []( const SUnit& Left, const SUnit& Right ) { return Left.Type < Right.Type; } );

 Cache.emplace( Count, pArmy );
 return *pArmy;
	}

	void Evaluate_VirtualScattered( benchmark::State& State )
	{
 const int32_t Count = static_cast<int32_t>( State.range( 0 ) );
 SArmy& Army = GetArmy( Count );
 for ( auto _ : State )
 {
 uint32_t Total = 0;
 for ( int32_t Index = 0; Index < Count; ++Index )
 {
 Total += Army.Scattered[ Index ]->Evaluate( static_cast<uint32_t>( Index ) );
 }
 benchmark::DoNotOptimize( Total );
 }
 State.SetItemsProcessed( State.iterations() * Count );
	}

	void Evaluate_TagMixed( benchmark::State& State )
	{
 const int32_t Count = static_cast<int32_t>( State.range( 0 ) );
 SArmy& Army = GetArmy( Count );
 for ( auto _ : State )
 {
 uint32_t Total = 0;
 for ( int32_t Index = 0; Index < Count; ++Index )
 {
 Total += EvaluateByTag( Army.Mixed[ Index ], static_cast<uint32_t>( Index ) );
 }
 benchmark::DoNotOptimize( Total );
 }
 State.SetItemsProcessed( State.iterations() * Count );
	}

	void Evaluate_TagGrouped( benchmark::State& State )
	{
 const int32_t Count = static_cast<int32_t>( State.range( 0 ) );
 SArmy& Army = GetArmy( Count );
 for ( auto _ : State )
 {
 uint32_t Total = 0;
 for ( int32_t Index = 0; Index < Count; ++Index )
 {
 Total += EvaluateByTag( Army.Grouped[ Index ], static_cast<uint32_t>( Index ) );
 }
 benchmark::DoNotOptimize( Total );
 }
 State.SetItemsProcessed( State.iterations() * Count );
	}

	BENCHMARK( Evaluate_VirtualScattered )->Arg( 262144 )->Unit( benchmark::kMicrosecond );
	BENCHMARK( Evaluate_TagMixed )->Arg( 262144 )->Unit( benchmark::kMicrosecond );
	BENCHMARK( Evaluate_TagGrouped )->Arg( 262144 )->Unit( benchmark::kMicrosecond );
}

int main( int argc, char** argv )
{
	NPerf::PinToFirstPerformanceCore();
	printf( "08_virtual_vs_tag\n" );
	printf( "sizeof( SUnit ) = %zu\n\n", sizeof( NPolymorphism::SUnit ) );
	benchmark::Initialize( &argc, argv );
	if ( benchmark::ReportUnrecognizedArguments( argc, argv ) )
	{
 return 1;
	}
	benchmark::RunSpecifiedBenchmarks();
	benchmark::Shutdown();
	return 0;
}
Если у вас массив маленький, то префетч данных не даст ничего даже на сложном паттерне (смотри левую колонку) ни на одной дистанции, а местами сделал даже хуже, добавив работы в алгоритм. Это ожидаемый результат, потому что данные уже в L2 и переносить нечего, а инструкции вы добавили и, к сожалению, так выглядит большинство мест, куда люди пытаются прикрутить несчастный префетч.
А вот когда данные реально большие и рабочий набор составляет мегабайты и паттерн доступа сложный, то префетч начинает работать (смотри вторую правую колонку), но обратите внимание на форму прироста, дистанция 4 элемента почти бесполезна, потому что данные, которые вы поставили на загрузку уже рядом лежат, и повторный запрос отбрасывается, для 8 и 16 становится лучше, подтягивая заранее часть данных, а оптимум получаем на 32, потому что, к тому моменту как
Process
добирается к нужным элементам, они уже лежат в кеше, и мы действительно через prefetch убрали узкое место, дав алгоритму работать без ожиданий.
А дальше опять становится хуже, потому что мы притащили данные заранее, но они опять далеко от рабочей области и успевают вытесниться до того, как понадобятся. Вот и получается что __mm_prefetch используется неправильно, и моя личная статистика фикса таких вещей показывает, что в 80% случаях применение неправильно, т.е либо не давал прироста, либо давал прирост отрицательный. Но вера в силу префетча у народа не угасает, и позволяет ему с легкостью проходить кодревью.
И не верьте человеку, который одним вызовом "prefetch" обещает вам иксы в алгоритме. Универсального правильного числа для префетча не существует и оно зависит от размера элемента, от того сколько работы делается на итерацию, от конкретного процессора, и подбирать это руками значит продавать всем игрокам, то что работало у вас на вашей машине. Если вы не можете назвать процессор на котором это будет работать, размер вашего рабочего массива и в какой уровень кеша влезают данные, то воткнутый "простотак" префетч в лучшем случае оставит вас при своих милисекундах.
